import bcrypt from 'bcryptjs'
import crypto from 'crypto'
import User from '../models/User.js'
import { sendMail } from '../utils/emailUtil.js'
import { signToken } from '../utils/tokenUtil.js'

const createTokenCookie = (res,user) => {
  const token = signToken({ id: user._id, role: user.role })
  res.cookie('token', token, { httpOnly:true, secure: process.env.NODE_ENV==='production', sameSite:'lax', maxAge:7*24*60*60*1000 })
  res.locals.token = token
  return token
}

export const register = async (req,res)=>{
  const { email, password, firstName, lastName } = req.body
  if(!email || !password || !firstName || !lastName) return res.status(400).json({ message:'Missing fields' })
  const existing = await User.findOne({ email })
  if(existing) return res.status(400).json({ message:'Email already in use' })
  const hashed = await bcrypt.hash(password, 12)
  const verificationToken = crypto.randomBytes(24).toString('hex')
  const role = email === "admin@gmail.com" ? "admin" : "user";

const user = await User.create({
  ...req.body,
  password: hashed,
  role,
  verificationToken,
  emailVerified: true
})
  await sendMail({ to: user.email, subject:'Verify your email', html:`<p>Verify your email with this link:</p><a href="${process.env.CLIENT_URL}/verify/${verificationToken}">${process.env.CLIENT_URL}/verify/${verificationToken}</a>` })
  const token = createTokenCookie(res,user)
  res.status(201).json({ token, user:{ id:user._id, firstName:user.firstName, lastName:user.lastName, email:user.email, phone:user.phone, emailVerified:user.emailVerified, role:user.role } })
}
export const login = async (req, res) => {
  const { email, password } = req.body;

  const user = await User.findOne({ email });

  if (!user) {
    return res.status(400).json({
      message: "Invalid credentials"
    });
  }

  const isMatch = await bcrypt.compare(password, user.password);

  if (!isMatch) {
    return res.status(400).json({
      message: "Invalid credentials"
    });
  }

  const token = createTokenCookie(res, user);

  res.json({
    token,
    user: {
      id: user._id,
      firstName: user.firstName,
      lastName: user.lastName,
      email: user.email,
      phone: user.phone,
      emailVerified: user.emailVerified,
      role: user.role
    }
  });
};
export const adminLogin = async (req, res) => {
  const { email, password } = req.body;

  const user = await User.findOne({ email });

  if (!user)
    return res.status(400).json({ message: "Invalid credentials" });

  const isMatch = await bcrypt.compare(password, user.password);

  if (!isMatch)
    return res.status(400).json({ message: "Invalid credentials" });

  if (user.role !== "admin")
    return res.status(403).json({
      message: "Access denied. Admin only."
    });

  const token = createTokenCookie(res, user);

  res.json({
    token,
    user: {
      id: user._id,
      firstName: user.firstName,
      lastName: user.lastName,
      email: user.email,
      role: user.role
    }
  });
};

export const logout = (req,res)=>{
  res.clearCookie('token').json({ message:'Logged out' })
}

export const verifyEmail = async (req,res)=>{
  const { token } = req.params
  const user = await User.findOne({ verificationToken: token })
  if(!user) return res.status(400).json({ message:'Invalid link' })
  user.emailVerified = true
  user.verificationToken = undefined
  await user.save()
  res.json({ message:'Email verified' })
}

export const forgotPassword = async (req,res)=>{
  const { email } = req.body
  const user = await User.findOne({ email })
  if(!user) return res.status(400).json({ message:'Email not found' })
  const resetToken = crypto.randomBytes(24).toString('hex')
  user.resetToken = resetToken
  user.resetTokenExpiry = Date.now() + 3600000
  await user.save()
  await sendMail({ to:user.email, subject:'Reset your password', html:`<p>Reset password by clicking:</p><a href="${process.env.CLIENT_URL}/reset-password/${resetToken}">${process.env.CLIENT_URL}/reset-password/${resetToken}</a>` })
  res.json({ message:'Reset email sent' })
}

export const resetPassword = async (req,res)=>{
  const { token } = req.params
  const { password } = req.body
  const user = await User.findOne({ resetToken: token, resetTokenExpiry: { $gt: Date.now() } })
  if(!user) return res.status(400).json({ message:'Invalid or expired token' })
  user.password = await bcrypt.hash(password, 12)
  user.resetToken = undefined
  user.resetTokenExpiry = undefined
  await user.save()
  createTokenCookie(res,user)
  res.json({ message:'Password reset' })
}

export const getProfile = async (req,res)=>{
  const { user } = req
  res.json({ user:{ id:user._id, firstName:user.firstName, lastName:user.lastName, email:user.email, phone:user.phone, addresses:user.addresses, payments:user.payments, emailVerified:user.emailVerified, role:user.role } })
}

export const updateProfile = async (req,res)=>{
  const updates = req.body
  if(updates.password) updates.password = await bcrypt.hash(updates.password, 12)
  const user = await User.findByIdAndUpdate(req.user._id, updates, { new:true })
  if(!user) return res.status(404).json({ message:'User not found' })
  res.json({ user:{ id:user._id, firstName:user.firstName, lastName:user.lastName, email:user.email, phone:user.phone, addresses:user.addresses, payments:user.payments, emailVerified:user.emailVerified, role:user.role } })
}

export const deleteAccount = async (req,res)=>{
  await User.findByIdAndDelete(req.user._id)
  res.clearCookie('token').json({ message:'Account deleted' })
}
